"""Generate a small, owned synthetic sample using existing test fixtures."""
from pathlib import Path
import json, subprocess, sys, shutil
root=Path(sys.argv[1]).resolve();root.mkdir(parents=True,exist_ok=True)
pkg=Path(__file__).resolve().parents[2]
subprocess.run([sys.executable,str(pkg/'test/make-fixtures.py'),str(root)],check=True)
shutil.copyfile(pkg/'test/fixtures/test-pixel.ttf',root/'font.ttf')
t={'version':1,'name':'editor-sample','fps':12,'seed':7,'tempo':{'beatSeconds':.413,'firstDownbeat':.25,'audioSource':'bed'},
   'sources':[{'id':'a','kind':'image','path':'a.png','pixelArt':True},{'id':'b','kind':'image','path':'b.png','pixelArt':True},{'id':'bed','kind':'audio','path':'bed.wav'}],
   'shots':[{'id':'base-and-title','kind':'image','source':'a','startBeat':0,'beats':2.2,'caption':{'lines':['KEEL'], 'font':'font.ttf','fontSize':8,'scale':1,'color':'#000000','typingCps':6}},
            {'id':'baked-dither','kind':'image','source':'b','startBeat':2.2,'beats':2,'transition':{'type':'dither','beats':.5,'pixelScale':2}},
            {'id':'card','kind':'card','startBeat':4.2,'beats':1,'text':{'lines':['EDIT'], 'font':'font.ttf','fontSize':8,'color':'#ffffff','background':'#281034'}}],
   'audio':[{'id':'music','source':'bed','role':'bed','startBeat':0,'beats':5.2,'gain':.8,'fadeOut':.1,'duck':[{'startBeat':1,'beats':1,'gain':.4}]},
            {'id':'sfx','source':'bed','role':'sfx','startBeat':1.3,'in':.7,'out':.85,'gain':.6,'fadeIn':.01}],
   'targets':[{'id':'wide','width':160,'height':90},{'id':'square','width':96,'height':96}]}
(root/'timeline.json').write_text(json.dumps(t,indent=2)+'\n')
(root/'ATTRIBUTION.md').write_text('Synthetic checkerboard images and beat audio generated by KEEL test/make-fixtures.py. Font is the generated MIT-licensed test-pixel.ttf fixture; its generator is test/make-font.py.\n')
